<template><view class="page"><PageHead :title="store.name||'发现好店'"/><view v-if="error" class="content error" @click="load">{{error}} · 重试</view><template v-if="store.id"><view class="store-header"><view class="row"><image :src="store.image" mode="aspectFill" class="logo"/><view><view class="title">{{store.name}}</view><text class="small link" @click="toggleFavorite('STORE',store.id)">{{isFavorite('STORE',store.id)?'★ 已收藏':'☆ 收藏店铺'}}</text><view class="stats"><text>{{Number(store.rating)>0?'★ '+store.rating:'暂无评分'}}</text><text>月售 {{store.sales}}+</text><text>{{store.minutes}}分钟</text></view><view class="tiny muted">{{store.zone}} · {{distanceText(location.point,store)}} · 配送 ¥{{money(store.delivery_fee)}}</view></view></view><view class="notice">{{store.open_now?'营业中':'未到营业时间'}} · {{store.opening_text}}</view><view class="notice"><text class="pill">公告</text><text>{{store.notice}}</text></view></view>
<view v-if="store.reservation_enabled||scheduledAt" class="card"><view class="bold">用餐时间</view><picker v-if="store.reservation_enabled" :range="slotLabels" @change="changeTime"><view class="field">{{slots.find(v=>v.value===scheduledAt)?.label||(scheduledAt?'原时段已失效，请重新选择':'尽快制作')}} ›</view></picker><button v-else class="btn light" :disabled="menu.loading" @click="changeTime({detail:{value:0}})">改为尽快制作</button><view class="tiny muted">{{store.reservation_enabled?'先选择日期和时间，再按该日剩余库存点餐':'商家已关闭预约，请改为尽快制作后重新选购。'}}</view></view><view class="tabs"><text v-for="t in ['点餐','评价','商家']" :class="{selected:tab===t}" :key="t" @click="tab=t">{{t}}</text></view>
<view v-if="tab==='点餐'" class="menu"><view class="categories"><view v-for="c in categories" :key="c" :class="{chosen:category===c}" @click="category=c">{{c}}</view></view><view class="products"><input v-model="search" class="field" placeholder="搜索本店菜品" confirm-type="search" @confirm="loadProducts"/><view class="category-title">{{category}}<text class="tiny muted"> / 每一口都用心</text></view><view v-for="p in products" :key="p.id" class="product"><image :src="p.image" mode="aspectFill" class="product-image"/><view class="product-body"><view class="product-name">{{p.name}}</view><text class="tiny link" @click="toggleFavorite('PRODUCT',p.id)">{{isFavorite('PRODUCT',p.id)?'★ 常点菜品':'☆ 收藏菜品'}}</text><view v-if="p.unavailable_reason" class="tiny muted">{{p.unavailable_reason}}</view><view v-if="p.sale_periods" class="tiny muted">售卖 {{p.sale_periods}}</view><view class="product-desc">{{p.description}}</view><view class="tiny muted">已售 {{p.sales}} · 余 {{p.stock}}</view><view class="between product-bottom"><text class="price">¥{{money(p.price)}}</text><view class="counter"><text v-if="quantity(p)>0&&!p.options?.length" class="counter-btn minus" @click="change(p,-1)">−</text><text v-if="quantity(p)>0" class="small">{{quantity(p)}}</text><text class="counter-btn" @click="selectProduct(p)">{{p.options?.length?'选':'+'}}</text></view></view></view></view><view v-if="menu.error" class="error" @click="loadProducts">{{menu.error}} · 重试</view><view v-if="menu.loading" class="small muted">正在加载菜品…</view><view v-if="products.length<menu.total" class="link" @click="more">加载更多菜品（{{products.length}} / {{menu.total}}）</view><view v-if="!menu.loading&&!menu.error&&!products.length" class="empty">这类商品正在准备中</view></view></view>
<view v-if="tab==='评价'" class="content"><view class="card"><view class="title">{{Number(store.rating)>0?store.rating:'暂无评分'}} <text v-if="Number(store.rating)>0" style="color:#c3a255">{{'★'.repeat(Math.round(Number(store.rating)))}}</text></view><view class="subtitle">每一份真实反馈，都让我们更好</view></view><view v-for="r in reviews" :key="r.id" class="card"><view class="between"><text>{{r.nickname}}</text><text class="pill">{{r.rating}} 分</text></view><view style="margin-top:20rpx">{{r.content}}</view><view v-if="r.reply" class="small muted" style="margin-top:16rpx">商家回复：{{r.reply}}</view></view><view v-if="!reviews.length" class="empty">还没有评价，期待你的第一条分享</view></view>
<view v-if="tab==='商家'" class="content"><view class="card stack"><view class="title">关于 {{store.name}}</view><text>{{store.description}}</text><text class="muted">营业时间：{{store.opening_text}}（北京时间）</text><text class="muted">配送范围：{{store.delivery_radius?'直线 '+store.delivery_radius+' 米内':'不限距离'}}</text><text class="muted">位置：{{store.zone}}</text><text class="muted">公告：{{store.notice}}</text><text class="link" @click="contact">联系商家：{{store.phone}}</text></view></view>
<view v-if="showCart" class="cart-mask" @click="showCart=false"><view class="cart-panel" @click.stop><view class="between"><text class="bold">已选商品</text><text class="small muted" @click="empty">清空</text></view><view v-for="p in currentItems" :key="p.lineKey||p.id" class="between cart-line"><view><view>{{p.name}}</view><view class="tiny muted">{{p.option_text}}</view><text class="price small">¥{{money(p.price*p.quantity)}}</text></view><view class="counter"><text class="counter-btn minus" @click="change(p,-1)">−</text><text>{{p.quantity}}</text><text class="counter-btn" @click="change(p,1)">+</text></view></view></view></view>
<view v-if="selection" class="cart-mask" @click="selection=null"><view class="cart-panel" @click.stop><view class="title">{{selection.name}}</view><view class="subtitle">选择规格</view><view class="chips"><view v-for="o in selection.options.filter(o=>o.kind==='SPEC')" :key="o.id" :class="['chip',{selected:specId===o.id}]" @click="specId=o.id">{{o.name}} ¥{{money(o.price)}} · 余{{o.stock}}</view></view><view class="subtitle">加料（可多选）</view><view class="chips"><view v-for="o in selection.options.filter(o=>o.kind==='ADDON')" :key="o.id" :class="['chip',{selected:addonIds.includes(o.id)}]" @click="toggleAddon(o.id)">{{o.name}} +¥{{money(o.price)}} · 余{{o.stock}}</view></view><button class="btn" style="margin-top:24rpx" @click="addSelection">加入购物车</button></view></view>
<view class="fixed-action cart-bar"><view class="row" @click="showCart=!showCart"><view class="basket">▣<text v-if="count" class="badge">{{count}}</text></view><view><text class="cart-price">¥{{money(total)}}</text><view class="tiny muted">配送 ¥{{money(store.delivery_fee)}} · ¥{{money(store.minimum)}}起送</view></view></view><button class="btn" :disabled="!count||(store.open_now===false&&!store.reservation_enabled)" @click="checkout">去结算 →</button></view></template></view></template>
<script setup>
import {ref,computed,reactive,watch} from 'vue';import {loadFavorites,isFavorite,toggleFavorite} from '../../lib/favorites';import {onLoad,onShow,onHide,onReachBottom} from '@dcloudio/uni-app';import PageHead from '../../components/PageHead.vue';import {request,cart,saveCart,clearCart,go,money,toast,confirm} from '../../lib/api';
import {location,locationActions} from '../../lib/location';import {distanceText} from '../../lib/geo.mjs';import {configureProduct,lineKey,availableToAdd} from '../../lib/options.mjs';
const slots=ref([]),scheduledAt=ref(''),slotLabels=computed(()=>['尽快制作',...slots.value.map(v=>v.label)]);
async function changeTime(e){const next=Number(e.detail.value)?slots.value[Number(e.detail.value)-1]?.value:'';if(next===undefined||next===scheduledAt.value)return;if(cart.storeId===id.value&&cart.items.length){if(!await confirm('更改用餐时间需要重新选择菜品，是否继续？'))return;clearCart()}scheduledAt.value=next;selection.value=null;await loadProducts()}
const selection=ref(null),specId=ref(null),addonIds=ref([]);function selectProduct(p){if(p.available===false||p.stock<=0)return toast(p.unavailable_reason||'菜品已售罄');if(!p.options?.length)return change(p,1);selection.value=p;specId.value=null;addonIds.value=[]}function toggleAddon(id){addonIds.value=addonIds.value.includes(id)?addonIds.value.filter(v=>v!==id):[...addonIds.value,id]}async function addSelection(){try{const p=configureProduct(selection.value,specId.value,addonIds.value);if(await change(p,1))selection.value=null}catch(e){toast(e.message)}}
import {createPagedCatalog,queryString} from '../../lib/paged-catalog.mjs';
const menu=reactive({rows:[],total:0,page:0,loading:false,error:''}),search=ref('');const feed=createPagedCatalog(menu,p=>request('/catalog/products?'+queryString(p),'GET',null,true));let searchTimer;function loadProducts(){clearTimeout(searchTimer);return feed.load({storeId:id.value,scheduledAt:scheduledAt.value,q:search.value.trim(),category:category.value==='全部商品'?'':category.value})}function more(){if(tab.value==='点餐')return feed.load(null,true)}let loadRevision=0;onHide(()=>{loadRevision++;clearTimeout(searchTimer);feed.cancel()});onReachBottom(more);
const id=ref(0),store=ref({}),reviews=ref([]),tab=ref('点餐'),category=ref('全部商品'),error=ref(''),showCart=ref(false);const categories=computed(()=>['全部商品',...(store.value.categories||[])]);const products=computed(()=>menu.rows);const currentItems=computed(()=>cart.storeId===id.value?cart.items:[]);const count=computed(()=>currentItems.value.reduce((s,p)=>s+p.quantity,0));const total=computed(()=>currentItems.value.reduce((s,p)=>s+p.quantity*p.price,0));function quantity(p){return p.options?.length?currentItems.value.filter(i=>i.id===p.id).reduce((n,i)=>n+i.quantity,0):currentItems.value.find(i=>lineKey(i)===lineKey(p))?.quantity||0}
watch([category,search],()=>{clearTimeout(searchTimer);searchTimer=setTimeout(loadProducts,300)});
async function change(p,delta){if(delta>0&&p.available===false)return toast(p.unavailable_reason||'当前不可购买');if(delta>0&&store.value.open_now===false&&!scheduledAt.value)return toast('商家未到营业时间');if(delta>0&&cart.storeId!==id.value&&cart.items.length){if(!await confirm('购物车中有其他商家的商品，是否清空并选择这家？'))return;clearCart()}cart.storeId=id.value;cart.scheduledAt=scheduledAt.value;const i=cart.items.find(i=>lineKey(i)===lineKey(p));const next=(i?.quantity||0)+delta;if(delta>0&&delta>availableToAdd(cart.items,p))return toast('已达到菜品、规格或加料可购买数量');if(next<=0)cart.items=cart.items.filter(i=>lineKey(i)!==lineKey(p));else if(i)i.quantity=next;else cart.items.push({...p,quantity:1});saveCart();return true}
async function empty(){if(await confirm('清空已选商品？')){clearCart();showCart.value=false}}function checkout(){go('checkout/index')}function contact(){uni.makePhoneCall({phoneNumber:store.value.phone})}async function load(){
 const ticket=++loadRevision,storeId=id.value
 const current=()=>ticket===loadRevision&&storeId===id.value
 error.value=''
 try{
  const info=await request('/stores/'+storeId+'/info');if(!current())return
  store.value=info
  const times=info.reservation_enabled?await request('/stores/'+storeId+'/slots'):[];if(!current())return
  slots.value=times
  if(cart.storeId===storeId)scheduledAt.value=cart.scheduledAt||''
  await loadProducts();if(!current())return
  const list=await request('/stores/'+storeId+'/reviews');if(!current())return
  reviews.value=list
 }catch(e){if(current())error.value=e.message}
}
onLoad(o=>{id.value=Number(o.id)});onShow(()=>{loadFavorites().catch(()=>{});locationActions.expire();if(id.value)load()});
</script>
<style scoped>
.store-header{padding:30rpx 32rpx;background:linear-gradient(115deg,#dfecdd,#f1f3df)}.logo{width:132rpx;height:132rpx;border-radius:26rpx;margin-right:25rpx}.store-header .title{font-size:36rpx}.stats{display:flex;gap:24rpx;font-size:24rpx;margin:14rpx 0;color:#6b835c}.stats text:first-child{color:#b48738}.notice{display:flex;align-items:center;gap:13rpx;margin-top:23rpx;font-size:22rpx;color:#849176;line-height:1.5}.notice .pill{flex-shrink:0}.tabs{display:flex;background:#fff;justify-content:space-around;padding:28rpx;font-size:29rpx;color:#95a28d}.tabs text{padding-bottom:10rpx}.tabs .selected{color:#315a3f;border-bottom:5rpx solid #648568;font-weight:700}.menu{display:flex;min-height:65vh;background:#fff}.categories{width:160rpx;flex-shrink:0;background:#f2f5ec}.categories view{padding:29rpx 18rpx;font-size:24rpx;line-height:1.6;color:#8c9882}.categories .chosen{background:white;color:#41633d;border-left:6rpx solid #5e8560;font-weight:700}.products{flex:1;padding:28rpx 22rpx;min-width:0}.category-title{font-weight:700;font-size:25rpx;margin-bottom:30rpx}.category-title text{font-weight:400;font-size:19rpx}.product{display:flex;gap:18rpx;margin-bottom:40rpx}.product-image{width:150rpx;height:165rpx;border-radius:17rpx;flex-shrink:0}.product-body{flex:1;min-width:0}.product-name{font-size:27rpx;font-weight:700}.product-desc{color:#97a18c;font-size:20rpx;line-height:1.5;margin:7rpx 0}.product-bottom{margin-top:10rpx}.product-bottom .price{font-size:29rpx}.counter{gap:12rpx}.counter-btn{width:39rpx;height:39rpx;font-size:29rpx}.cart-bar{display:flex;justify-content:space-between;align-items:center;padding-top:16rpx}.basket{font-size:45rpx;background:#edf2e5;color:#55744b;border-radius:50%;width:80rpx;height:80rpx;display:flex;align-items:center;justify-content:center;margin-right:20rpx;position:relative}.badge{position:absolute;top:-4rpx;right:-4rpx;background:#d89952;color:#fff;border-radius:50%;min-width:28rpx;font-size:20rpx;text-align:center}.cart-price{font-size:37rpx;font-weight:750}.cart-bar .btn{padding:23rpx 35rpx}.cart-mask{position:fixed;inset:0;background:#0005;z-index:9}.cart-panel{position:absolute;bottom:135rpx;left:0;right:0;background:#fff;padding:35rpx;border-radius:30rpx 30rpx 0 0;max-height:60vh;overflow:auto}.cart-line{margin-top:30rpx}
</style>
